def minPath(grid, k):
    n = len(grid)
    # Find the position of the first cell with value 1
    pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                pos = (i, j)
                break
        if pos:
            break

    # If there is no 1 in the grid, just return a list of zeros
    if pos is None:
        return [0] * k

    i, j = pos
    # Collect values of the valid neighboring cells
    neighbors = []
    if i > 0:
        neighbors.append(grid[i - 1][j])
    if i < n - 1:
        neighbors.append(grid[i + 1][j])
    if j > 0:
        neighbors.append(grid[i][j - 1])
    if j < n - 1:
        neighbors.append(grid[i][j + 1])

    # Minimum neighbor value (default to 0 if no neighbors)
    val = min(neighbors) if neighbors else 0

    # Build the alternating answer list
    ans = []
    for idx in range(k):
        ans.append(1 if idx % 2 == 0 else val)
    return ans
